// One item per URL: the primary feed and, when given, its fallback.
const FEEDS = [
  [
    "BusinessWorld",
    "https://www.bworldonline.com/feed/",
    "https://www.bworldonline.com/rss/"
  ],
  [
    "Inquirer Business",
    "https://business.inquirer.net/feed",
    "https://newsinfo.inquirer.net/feed"
  ],
  [
    "Philstar Business",
    "https://www.philstar.com/rss/business",
    "https://www.philstar.com/rss/headlines"
  ],
  [
    "gCaptain",
    "https://gcaptain.com/feed/",
    "https://gcaptain.com/feed/?post_type=post"
  ],
  [
    "Splash247",
    "https://splash247.com/feed/",
    "https://splash247.com/rss"
  ],
  [
    "Seatrade Maritime",
    "https://www.seatrade-maritime.com/rss.xml",
    "https://www.seatrade-maritime.com/rss"
  ],
  [
    "Google News · PSEi",
    "https://news.google.com/rss/search?q=PSEi%20OR%20%22Philippine%20Stock%20Exchange%22&hl=en-PH&gl=PH&ceid=PH:en",
    ""
  ]
];
const items = [];
for (const [name, url, fallback] of FEEDS) {
  items.push({ json: { name, url, kind: 'primary' } });
  if (fallback) items.push({ json: { name, url: fallback, kind: 'fallback' } });
}
return items;

// Pair each HTTP result with its feed row and decide: OK feed / not a feed / HTTP error.
const rows = $('Feed List').all().map(i => i.json);
const results = $input.all().map((it, idx) => {
  const r = rows[idx] || {};
  const j = it.json || {};
  const body = typeof j.data === 'string' ? j.data : (typeof j === 'string' ? j : '');
  const status = j.error ? (j.error.httpCode || j.error.status || 'ERR') : (j.statusCode || 200);
  const head = body.slice(0, 4000);
  const isRss = /<rss[\s>]/i.test(head), isAtom = /<feed[\s>]/i.test(head);
  const items = (body.match(/<item[\s>]/gi) || []).length + (body.match(/<entry[\s>]/gi) || []).length;
  const dateM = body.match(/<(?:pubDate|updated|dc:date)>([^<]+)</i);
  const title = (head.match(/<title[^>]*>(?:<!\[CDATA\[)?([^<\]]+)/i) || [])[1] || '';
  const verdict = j.error ? 'HTTP ' + status + ' ' + String(j.error.message || '').slice(0, 60)
    : (isRss || isAtom) ? (items ? 'OK ' + (isRss ? 'RSS' : 'Atom') + ' · ' + items + ' items' : 'feed but 0 items')
    : /<html/i.test(head) ? 'HTML page, not a feed' : 'unknown body (' + body.length + ' bytes)';
  return { json: { name: r.name, kind: r.kind, url: r.url, status, verdict, ok: !j.error && (isRss || isAtom) && items > 0, title: title.trim(), newest: dateM ? dateM[1].trim() : '' } };
});
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = results.map(x => (x.ok ? '✅' : '❌') + ' <b>' + esc(x.name) + '</b>' + (x.kind === 'fallback' ? ' (fallback)' : '') + ' — ' + esc(x.verdict) + (x.newest ? ' · newest ' + esc(x.newest) : '') + '\n<i>' + esc(x.url) + '</i>');
const text = '<b>📡 Feed probe</b> · ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC\n\n' + lines.join('\n\n');
return [{ json: { text, results } }];
